const item = $input.item;
const b = item.binary && item.binary.data;
if (b) {
  const mime = (b.mimeType || '').toLowerCase();
  const map = { 'audio/ogg':'ogg','audio/opus':'opus','audio/mpeg':'mp3','audio/mp4':'m4a','audio/x-m4a':'m4a','audio/wav':'wav','audio/x-wav':'wav','audio/webm':'webm','audio/flac':'flac' };
  const ok = ['flac','mp3','mp4','mpeg','mpga','m4a','ogg','opus','wav','webm'];
  let ext = map[mime];
  if (!ext) { const m = (b.fileName||'').toLowerCase().match(/\.([a-z0-9]+)$/); ext = (m && ok.includes(m[1])) ? m[1] : 'ogg'; }
  b.fileName = 'audio.' + ext;
  if (!b.mimeType) b.mimeType = 'audio/ogg';
}
return item;

const src = $('Gatilho Telegram').item.json;
const text = String($json.text || '').trim();
const out = JSON.parse(JSON.stringify(src));
if (out.message) { out.message.text = text; delete out.message.voice; delete out.message.audio; }
return { json: out };

const e = $input.item.json;
const updateId = e.update_id || null;
let userId, chatId, type, text='', callbackData='', firstName='', callbackQueryId=null;
let msgId=null, msgText='';
if (e.message) {
  userId = e.message.from.id; chatId = e.message.chat.id; firstName = e.message.from.first_name || '';
  if (typeof e.message.text === 'string' && e.message.text.trim().length) { type='text'; text=e.message.text.trim(); } else { type='non_text'; }
} else if (e.callback_query) {
  userId = e.callback_query.from.id; chatId = e.callback_query.message.chat.id; firstName = e.callback_query.from.first_name || '';
  type='callback'; callbackData = e.callback_query.data || ''; callbackQueryId = e.callback_query.id; msgId = e.callback_query.message.message_id; msgText = e.callback_query.message.text || '';
}
const isCommand = type==='text' && text.startsWith('/');
const command = isCommand ? text.split(/\s+/)[0].toLowerCase() : '';
return { json: { userId, chatId, type, text, callbackData, firstName, isCommand, command, callbackQueryId, updateId, msgId, msgText } };

const n = $('Normalizar').first().json;
const s = $input.item.json;
const ps = s.placement_state || null;
const ts = s.teacher_state || null;
const cb = String(n.callbackData || '');
const cmd = n.command || '';
let route, subroute = '';
if (cmd === '/reset' || cmd === '/resetfull') { route='onboarding'; subroute='reset'; } // DEV /reset,/resetfull — remover na versao final
else if (cmd === '/pausa' || cb === 'pl_pause') { route='placement'; subroute='pause'; }
else if (cmd === '/continuar' || cb === 'pl_resume') { route='placement'; subroute='resume'; }
else if (cmd === '/nivel') { route='placement'; subroute='restart'; }
else if (ps && ps.status === 'in_progress') {
  if (n.type==='callback' && cb.startsWith('ans_')) { route='placement'; subroute='answer'; }
  else if (n.type==='text' && !n.isCommand) { route='placement'; subroute='answer'; }
  else { route='system_msg'; subroute='in_test'; }
}
else if (ps && ps.status === 'paused') { route='system_msg'; subroute='paused'; }
else if (s.profile && s.profile.int_await===true && n.type==='text' && !n.isCommand) { route='interests'; subroute='add_custom'; }
else if (s.onboarding === 'pick_persona') { if (n.type==='callback' && cb.startsWith('persona_')) { route='config'; subroute='set'; } else { route='config'; subroute='menu'; } }
else if (s.onboarding === 'pick_interests') { if (n.type==='callback' && cb.startsWith('int_')) { route='interests'; subroute=(cb==='int_done'?'done':(cb==='int_other'?'other':'toggle')); } else { route='interests'; subroute='menu'; } }
else if (s.onboarding !== 'done' && s.onboarding !== 'placement_intro') { route='onboarding'; subroute='step'; }
else if (s.onboarding === 'placement_intro') {
  if (cb.startsWith('pl_start_')) { route='placement'; subroute='start'; }
  else { route='onboarding'; subroute='step'; }
}
else if (cmd === '/start') { route='menu'; }
else if (n.type==='callback' && cb.startsWith('mode_')) { route='mode_switch'; }
else if (cmd === '/config' || cmd === '/persona' || cb === 'cfg_open') { route='config'; subroute='menu'; }
else if (n.type==='callback' && cb.startsWith('persona_')) { route='config'; subroute='set'; }
else if (cmd === '/interesses' || cb === 'int_open') { route='interests'; subroute='menu'; }
else if (n.type==='callback' && cb.startsWith('int_')) { route='interests'; subroute=(cb==='int_done'?'done':(cb==='int_other'?'other':'toggle')); }
else if (cmd === '/menu' || cmd === '/modo') { route='menu'; }
else if (cmd === '/progresso' || cmd === '/perfil') { route='system_msg'; subroute='progress'; }
else if (cmd === '/help' || cmd === '/ajuda') { route='system_msg'; subroute='help'; }
else if (n.isCommand) { route='system_msg'; subroute='unknown'; }
else if (n.type === 'non_text') { route='system_msg'; subroute='non_text'; }
else if (s.mode === 'teacher') {
  route='professor';
  const tph = ts ? ts.phase : null;
  if (n.type==='callback' && cb==='t_doubt') subroute='ask_doubt';
  else if (n.type==='callback' && cb==='t_start') subroute='start_quiz';
  else if (tph==='quiz' && n.type==='text' && !n.isCommand) subroute='check';
  else if (tph==='doubt' && n.type==='text' && !n.isCommand) subroute='doubt_msg';
  else if (tph==='intro' && n.type==='text' && !n.isCommand) subroute='doubt_msg';
  else subroute='intro';
}
else { route='conversa'; }
return { json: { ...s, ...n, route, subroute } };

const d = $input.item.json;
function sanitizeName(s){ return String(s||'').replace(/[^a-zA-Z\u00C0-\u024F\s'\-]/g,'').slice(0,50).trim(); }
function q(v){ return (v===null||v===undefined)?'NULL':"'"+String(v).replace(/'/g,"''")+"'"; }
function extractName(raw){ var s=String(raw||'').trim(); while(s.length && '.!?,'.indexOf(s.charAt(s.length-1))>=0){ s=s.slice(0,-1).trim(); } var low=s.toLowerCase(); var prefs=['o meu nome eh ','o meu nome e ','o meu nome é ','meu nome eh ','meu nome e ','meu nome é ','me chamo ','chamo-me ','chamo me ','pode me chamar de ','nome: ','nome:','eu sou o ','eu sou a ','eu sou ','sou o ','sou a ','sou ','eh ','é ','e ']; for(var i=0;i<prefs.length;i++){ if(low.indexOf(prefs[i])===0){ s=s.slice(prefs[i].length).trim(); break; } } var stop=['e','de','da','do','dos','das','que','tenho','anos','ano','eu','meu','minha','nome','sou','um','uma']; var words=s.split(' ').filter(function(w){return w.length>0;}); var out=[]; for(var k=0;k<words.length;k++){ var lw=words[k].toLowerCase(); if(stop.indexOf(lw)>=0) break; out.push(words[k]); if(out.length>=2) break; } return out.join(' '); }
let next, reply, sendKind='text', saveName=null, saveAge=null;
const isReset = (d.command === '/reset' || d.command === '/resetfull'); // DEV — remover na versao final
const isFull = (d.command === '/resetfull'); // DEV /resetfull — remover na versao final
const ob = isReset ? 'new' : d.onboarding;
if (!ob || ob==='new') { next='awaiting_name'; reply='Oi! 👋 Eu sou o <b>IAChat</b>, seu tutor de inglês pessoal aqui no Telegram.\n\nMeu objetivo é te ajudar a <b>aprender e praticar inglês</b> do seu jeito — conversando sobre o que você curte e treinando justamente os pontos onde você mais erra.\n\nPra deixar tudo com a sua cara, primeiro preciso te conhecer um pouco. 😊\n\nPra começar: <b>qual é o seu nome?</b>'; }
else if (ob==='awaiting_name') { saveName=sanitizeName(extractName(d.text)); if(!saveName){ next='awaiting_name'; reply='Hmm, não entendi 😊 Pode escrever só o seu nome?'; } else { next='awaiting_age'; reply='Prazer, '+saveName+'! Quantos anos você tem?'; } }
else if (ob==='awaiting_age') { const m=(String(d.text||'').match(/\d{1,2}/)||[])[0]; if(!m){ next='awaiting_age'; reply='Só o número, por favor 😊 Quantos anos você tem?'; } else { saveAge=parseInt(m,10); next='placement_intro'; sendKind='level_pick'; reply='Show! 🙌 Agora me conta: como você se sente com o seu inglês hoje? 👇\n\n📝 Assim que você escolher, vou iniciar um <b>teste de 10 questões</b> pra avaliar o seu nível.\n\n⚠️ <b>Responda com sinceridade e sem nenhuma ajuda externa</b> (tradutor, internet, outra pessoa) — é o seu número de acertos e erros que me permite te dar a melhor experiência. 🙂'; } }
else { next='placement_intro'; sendKind='level_pick'; reply='Como você se sente com o seu inglês hoje? 👇\n\n📝 Ao escolher, começa um <b>teste de 10 questões</b>. Responda com <b>sinceridade e sem ajuda externa</b> — é isso que garante a melhor experiência. 🙂'; }
const sets=['onboarding='+q(next),'updated_at=now()'];
if(isReset){ sets.push('placement_state=NULL','teacher_state=NULL'); } // DEV /reset — remover na versao final
if(isFull){ sets.push("profile='{}'::jsonb","level=NULL","mode='chat'","xp=0","streak_count=0","last_active=NULL","badges='[]'::jsonb","msg_count=0","name=NULL","age=NULL"); } // DEV /resetfull — remover na versao final
if(saveName!==null) sets.push('name='+q(saveName));
if(saveAge!==null) sets.push('age='+parseInt(saveAge,10));
const sql='UPDATE students SET '+sets.join(', ')+' WHERE user_id='+parseInt(d.userId,10)+';';
return { json: { ...d, next, reply, sendKind, saveName, saveAge, sql } };

const d = $('Roteador Mestre').first().json;
const sub = d.subroute;
const bank = $input.all().map(r=>r.json);
const uid = parseInt(d.userId,10);
function q(v){ return (v===null||v===undefined)?'NULL':"'"+String(v).replace(/'/g,"''")+"'"; }
function norm(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s]/g,'').replace(/\s+/g,' ').trim(); }
function q(v){ return (v===null||v===undefined)?'NULL':"'"+String(v).replace(/'/g,"''")+"'"; }
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function norm(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s]/g,'').replace(/\s+/g,' ').trim(); }
function _expand(s){ return s.replace(/[\u2018\u2019\u0060]/g,"'")
  .replace(/\bi'm\b/g,'i am').replace(/\byou're\b/g,'you are').replace(/\bwe're\b/g,'we are').replace(/\bthey're\b/g,'they are')
  .replace(/\bhe's\b/g,'he is').replace(/\bshe's\b/g,'she is').replace(/\bit's\b/g,'it is').replace(/\bthat's\b/g,'that is')
  .replace(/\bdon't\b/g,'do not').replace(/\bdoesn't\b/g,'does not').replace(/\bdidn't\b/g,'did not')
  .replace(/\bcan't\b/g,'can not').replace(/\bwon't\b/g,'will not').replace(/\bisn't\b/g,'is not').replace(/\baren't\b/g,'are not')
  .replace(/\bwasn't\b/g,'was not').replace(/\bweren't\b/g,'were not').replace(/\bhaven't\b/g,'have not').replace(/\bhasn't\b/g,'has not')
  .replace(/\bi've\b/g,'i have').replace(/\byou've\b/g,'you have').replace(/\bi'll\b/g,'i will').replace(/\bi'd\b/g,'i would'); }
function normW(s){ var x=String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''); x=_expand(x); return x.replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim(); }
var _LEAD=['the','a','an','it','is','its','it is','they','them','he','she','we','i','to','that','this','answer','resposta','well','so','their'];
function _stripLead(t){ var changed=true; while(changed && t.length>1){ changed=false; for(var k=0;k<_LEAD.length;k++){ var fw=_LEAD[k].split(' '); if(fw.length<=t.length){ var ok=true; for(var j=0;j<fw.length;j++){ if(t[j]!==fw[j]){ ok=false; break; } } if(ok){ t=t.slice(fw.length); changed=true; break; } } } } return t; }
// Forgiving comparison for WRITTEN answers (fill-the-blank). MC stays exact elsewhere.
function answersMatch(given, answer){ var g=normW(given), a=normW(answer); if(!a) return false; if(g===a) return true; var gt=g.split(' '), at=a.split(' '); for(var i=0;i+at.length<=gt.length;i++){ var hit=true; for(var j=0;j<at.length;j++){ if(gt[i+j]!==at[j]){ hit=false; break; } } if(hit) return true; } if(_stripLead(gt.slice()).join(' ')===a) return true; if(at.length===1 && gt.indexOf(at[0])>=0) return true; return false; }

const LEVELS=['A1','A2','B1','B2','C1'];
function clampLevel(i){ return LEVELS[Math.max(0,Math.min(LEVELS.length-1,i))]; }
const profile=(d.profile&&typeof d.profile==='object')?d.profile:{};
let ps=d.placement_state||null;
const TOTAL=10;
let out={ send_kind:'', text:'', gabarito:'', resultText:'', sql:'' };
function qById(id){ return bank.find(b=>b.id===id); }
function buildState(startLevel){
  const li=LEVELS.indexOf(startLevel);
  const order=[li,li+1,li-1,li+2,li-2];
  const picked=[]; const used=new Set(); let guard=0;
  while(picked.length<TOTAL && guard<300){
    for(const lv of order){ const L=LEVELS[lv]; if(!L) continue; const pool=bank.filter(b=>b.cefr_level===L && !used.has(b.id)); if(pool.length){ const it=pool[(picked.length+guard)%pool.length]; used.add(it.id); picked.push(it.id); if(picked.length>=TOTAL) break; } }
    guard++;
  }
  return { status:'in_progress', qids:picked, idx:0, answers:[], level:startLevel, start_level:startLevel, streak_ok:0, streak_bad:0 };
}
function render(qq, idx){ let t='Questão '+(idx+1)+'/'+TOTAL+'\n\n'+esc(qq.prompt); if(qq.qtype==='mc'&&Array.isArray(qq.options)){ const L=['A','B','C','D','E']; t+='\n\n'+qq.options.map((o,i)=>L[i]+') '+esc(o)).join('\n'); } else { t+='\n\n(escreva sua resposta)'; } return t; }
if(sub==='start' || sub==='restart'){
  let startLevel='A2'; const cb=String(d.callbackData||'');
  if(cb.startsWith('pl_start_')) startLevel=cb.replace('pl_start_','');
  if(sub==='restart') startLevel=(profile.level||d.level||'A2');
  if(!LEVELS.includes(startLevel)) startLevel='A1';
  ps=buildState(startLevel);
  const qq=qById(ps.qids[0]);
  out.send_kind = qq.qtype==='mc'?'mc':'written';
  out.text=render(qq,0);
  out.sql='UPDATE students SET placement_state='+q(JSON.stringify(ps))+"::jsonb, onboarding='done', updated_at=now() WHERE user_id="+uid+'; INSERT INTO placement_attempts (user_id, started_at) VALUES ('+uid+', now());';
}
else if(sub==='pause'){
  if(ps && ps.status==='in_progress'){ ps.status='paused'; out.send_kind='pause'; out.text='Teste pausado ⏸️ Seu progresso está salvo. Toque em [▶️ Continuar] quando quiser retomar.'; out.sql='UPDATE students SET placement_state='+q(JSON.stringify(ps))+'::jsonb, updated_at=now() WHERE user_id='+uid+';'; }
  else { out.send_kind='pause'; out.text='Não há teste em andamento para pausar 😊'; out.sql='UPDATE students SET updated_at=now() WHERE user_id='+uid+';'; }
}
else if(sub==='resume'){
  if(ps && ps.status==='paused'){ ps.status='in_progress'; const qq=qById(ps.qids[ps.idx]); out.send_kind=qq.qtype==='mc'?'mc':'written'; out.text='De volta! ▶️\n\n'+render(qq,ps.idx); out.sql='UPDATE students SET placement_state='+q(JSON.stringify(ps))+'::jsonb, updated_at=now() WHERE user_id='+uid+';'; }
  else { out.send_kind='pause'; out.text='Não há teste pausado para continuar 😊'; out.sql='UPDATE students SET updated_at=now() WHERE user_id='+uid+';'; }
}
else if(sub==='answer'){
  const qq=qById(ps.qids[ps.idx]);
  let given=d.text||''; const cb=String(d.callbackData||'');
  if(cb.startsWith('ans_')){ const letter=cb.replace('ans_',''); const li=['A','B','C','D','E'].indexOf(letter); if(qq.qtype==='mc'&&Array.isArray(qq.options)&&li>=0&&li<qq.options.length) given=qq.options[li]; }
  let ok;
  if(qq.qtype==='mc'&&Array.isArray(qq.options)){ const L=['a','b','c','d','e']; const li=L.indexOf(norm(given)); const chosen=(li>=0&&li<qq.options.length)?qq.options[li]:given; ok=norm(chosen)===norm(qq.answer); }
  else { ok=answersMatch(given, qq.answer); }
  ps.answers.push({ qid:qq.id, given:given, correct:qq.answer, ok:ok, skill:qq.skill, prompt:qq.prompt, explanation:qq.explanation });
  if(ok){ ps.streak_ok++; ps.streak_bad=0; if(ps.streak_ok>=2){ ps.level=clampLevel(LEVELS.indexOf(ps.level)+1); ps.streak_ok=0; } }
  else { ps.streak_bad++; ps.streak_ok=0; if(ps.streak_bad>=2){ ps.level=clampLevel(LEVELS.indexOf(ps.level)-1); ps.streak_bad=0; } }
  ps.idx++;
  if(ps.idx>=TOTAL || ps.idx>=ps.qids.length){
    const correctCount=ps.answers.filter(a=>a.ok).length;
    const score=Math.round((correctCount/ps.answers.length)*100);
    const finalLevel=ps.level;
    const skillPT={grammar:'gramática',vocabulary:'vocabulário',reading:'leitura'};
    const gb=ps.answers.map((a,i)=>{ const head=esc(String(a.prompt).split('\n')[0]); let b=(i+1)+'. '+(a.ok?'✅':'❌')+' '+head+'\n      🗣️ Você: '+esc(a.given||'—'); if(!a.ok){ b+='\n      ✔️ Correta: '+esc(a.correct)+'\n      💡 '+esc(a.explanation); } return b; }).join('\n\n');
    const bySkill={}; ps.answers.forEach(a=>{ bySkill[a.skill]=bySkill[a.skill]||{ok:0,n:0}; bySkill[a.skill].n++; if(a.ok)bySkill[a.skill].ok++; });
    const weak=Object.keys(bySkill).filter(s=>bySkill[s].ok/bySkill[s].n<0.6);
    profile.level=finalLevel;
    out.send_kind='gabarito';
    out.gabarito='🎯 Seu nível estimado: '+finalLevel+'\n✅ Acertos: '+correctCount+'/'+ps.answers.length+' ('+score+'%)\n'+(weak.length?('📌 Reforçar: '+weak.map(s=>skillPT[s]||s).join(', ')):'🌟 Mandou bem em todas as áreas!')+'\n\n━━━━━━━━━━━━\n📋 Gabarito detalhado\n━━━━━━━━━━━━\n\n'+gb;
    out.resultText='E aí, como você quer continuar? 👇';
    const answersJson=JSON.stringify(ps.answers);
    out.sql='UPDATE students SET placement_state=NULL, onboarding='+q('pick_persona')+', level='+q(finalLevel)+', profile='+q(JSON.stringify(profile))+'::jsonb, updated_at=now() WHERE user_id='+uid+'; UPDATE placement_attempts SET finished_at=now(), level_result='+q(finalLevel)+', score='+score+', answers='+q(answersJson)+'::jsonb WHERE id=(SELECT id FROM placement_attempts WHERE user_id='+uid+' ORDER BY started_at DESC LIMIT 1);';
  } else {
    const nq=qById(ps.qids[ps.idx]);
    out.send_kind=nq.qtype==='mc'?'mc':'written';
    out.text=(ok?'✅ <b>Acertou!</b>':'❌ <b>Quase lá</b>')+'\n➖➖➖➖➖➖➖➖\n\n'+render(nq,ps.idx);
    out.sql='UPDATE students SET placement_state='+q(JSON.stringify(ps))+'::jsonb, updated_at=now() WHERE user_id='+uid+';';
  }
}
return { json: { ...d, ...out } };

const d=$input.item.json;
if(!d.name || !d.age){ const sql='UPDATE students SET updated_at=now() WHERE user_id='+parseInt(d.userId,10)+';'; return { json:{ ...d, mode:d.mode||'chat', sql, confirm:'Vamos primeiro terminar seu cadastro! Digite /start 😊' } }; }
const mode = d.callbackData==='mode_teacher' ? 'teacher' : 'chat';
const sql="UPDATE students SET mode='"+mode+"', onboarding='done', updated_at=now() WHERE user_id="+parseInt(d.userId,10)+';';
const confirm = mode==='teacher' ? '📚 Modo Professor! Vou te passar exercícios focados no que você mais erra. Mande qualquer mensagem para receber o primeiro 😊' : '💬 Modo Conversa! Bora bater um papo. So, what did you do today? 😊';
return { json:{ ...d, mode, sql, confirm } };

const item=$input.first().json;
const raw=(item.output && String(item.output).trim().length)?String(item.output):'Hmm, não entendi direito — pode repetir? 😊';
const LIMIT=4000;
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
function split(t,limit){ const chunks=[]; let rest=t; while(rest.length>limit){ let cut=rest.lastIndexOf('\n',limit); if(cut<limit*0.5) cut=rest.lastIndexOf(' ',limit); if(cut<limit*0.5) cut=limit; chunks.push(rest.slice(0,cut)); rest=rest.slice(cut).replace(/^\s+/,''); } if(rest.length) chunks.push(rest); return chunks; }
const parts=split(esc(raw),LIMIT);
return parts.map((p,i)=>({ json:{ messageText:p, partIndex:i+1, partTotal:parts.length } }));

const d=$('Roteador Mestre').first().json;
const uid=parseInt(d.userId,10);
const name=d.name||'aluno';
const p=(d.profile&&typeof d.profile==='object')?d.profile:{};
let lvl=(p.level||d.level||'A1').toUpperCase();
const TRACK={
A1:[['Cumprimentos','saudações: hello, hi, good morning/afternoon/evening/night, how are you, I am fine, goodbye, see you, thank you'],['Alfabeto','o alfabeto inglês A-Z, nomes das letras e soletrar palavras simples'],['Números','números cardinais de 0 a 100, como dizer e escrever'],['Cores e animais','cores (red, blue, green, yellow, black, white) e animais comuns (dog, cat, bird, fish, horse)'],['Pronomes pessoais','pronomes sujeito: I, you, he, she, it, we, they'],['Verbo to be','formas afirmativas do verbo to be: I am, you/we/they are, he/she/it is'],['Negativa','negativa com to be: I am not, he is not (isnt), they are not (arent)'],['Interrogativa','perguntas sim/não com to be (Are you...? Is he...?) e respostas curtas (Yes, I am / No, he isnt)'],['Nacionalidade e clima','nacionalidades (Brazilian, American, English) e clima (sunny, rainy, cold, hot, windy)'],['Perguntas com WH','perguntas com what, who, where, when, why, how usando to be']],
