function answersMatch(g,a){ g=norm(g); a=norm(a); if(!a) return false; if(g===a) return true; var _gs=g.replace(/\s+/g,''),_as=a.replace(/\s+/g,''); if(_as.length>=2&&_gs===_as) return true; if(_as.length>=3&&_gs.indexOf(_as)>=0) return true; if(g.indexOf(a)>=0) return true; if(a.indexOf(g)>=0&&g.length>=2) return true; var gt=g.split(' '),at=a.split(' '); for(var i=0;i+at.length<=gt.length;i++){var h=true;for(var j=0;j<at.length;j++){if(gt[i+j]!==at[j]){h=false;break;}}if(h)return true;} return false; }
